class DashboardController < ApplicationController
  def index
    @start_date = parse_date(params[:start_date])
    @end_date = parse_date(params[:end_date])

    @orders = Order.between_dates(@start_date, @end_date).ordered

    @total = @orders.sum(:amount).to_d
    @count = @orders.count
    @average = @count.positive? ? (@total / @count) : 0.to_d
    @by_category = @orders.group(:category).sum(:amount)
    @empty = @count.zero?
  end

  private

  def parse_date(value)
    return nil if value.blank?

    Date.parse(value.to_s)
  rescue ArgumentError, TypeError
    nil
  end
end

class Order < ApplicationRecord
  validates :amount, presence: true, numericality: { greater_than_or_equal_to: 0 }
  validates :category, presence: true
  validates :order_date, presence: true

  scope :between_dates, ->(start_date, end_date) {
    relation = all
    relation = relation.where(order_date: start_date..) if start_date.present?
    relation = relation.where(order_date: ..end_date) if end_date.present?
    relation
  }

  scope :ordered, -> { order(order_date: :asc, id: :asc) }
end

