body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: #f5f6f8;
  color: #1f2933;
}

#dashboard {
  max-width: 960px;
  margin: 0 auto;
  padding: 24px 16px 48px;
