#filter-form {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 12px;
  background: #ffffff;
  border: 1px solid #e4e7eb;
  border-radius: 8px;
  padding: 16px;
  margin-bottom: 24px;
}

.filter-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.filter-field label {
  font-size: 13px;
  color: #52606d;
}

.filter-field input[type="date"] {
  padding: 8px 10px;
  border: 1px solid #cbd2d9;
  border-radius: 6px;
  font-size: 14px;
}

