  background: #1d4ed8;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-bottom: 24px;
}

.metric {
  display: flex;
  flex-direction: column;
  gap: 8px;
  background: #ffffff;
  border: 1px solid #e4e7eb;
  border-radius: 8px;
  padding: 16px;
}

.metric-label {
  font-size: 13px;
  color: #52606d;
}

.metric span:last-child {
  font-size: 24px;
  font-weight: 700;
}

.chart-section,
.table-section {
  background: #ffffff;
  border: 1px solid #e4e7eb;
  border-radius: 8px;
  padding: 16px;
  margin-bottom: 24px;
}

#chart {
  display: flex;
  align-items: flex-end;
  gap: 24px;
  height: 240px;
  padding: 16px 8px 0;
  border-bottom: 2px solid #cbd2d9;
}

.chart-bar {
  position: relative;
  flex: 1;
  min-width: 40px;
  max-width: 120px;
  min-height: 4px;
  background: linear-gradient(180deg, #3b82f6, #2563eb);
  border-radius: 4px 4px 0 0;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
}

.bar-label {
  position: absolute;
  bottom: -22px;
  font-size: 12px;
  color: #52606d;
  white-space: nowrap;
}

.bar-value {
  position: absolute;
  top: -20px;
  font-size: 12px;
  font-weight: 600;
  color: #1f2933;
  white-space: nowrap;
}

#orders-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

#orders-table th,
#orders-table td {
  text-align: left;
  padding: 10px 12px;
  border-bottom: 1px solid #e4e7eb;
}

#orders-table th {
  background: #f0f4f8;
  font-weight: 600;
  color: #52606d;
}

#orders-table tbody tr:hover {
  background: #f8fafc;
}

#empty-state {
  background: #ffffff;
  border: 1px dashed #cbd2d9;
  border-radius: 8px;
  padding: 48px 16px;
  text-align: center;
  color: #52606d;
}
"}

